"""Proposal schema definition with 8 required fields."""
from dataclasses import dataclass, field, asdict
from typing import Optional, List
from datetime import datetime
import json

# 8 required fields for proposal schema
PROPOSAL_REQUIRED_FIELDS = [
    "proposal_id",
    "title",
    "physics_domain",
    "physical_goal",
    "implementation_path",
    "machine_criteria",
    "source_node_id",
    "priority_score",
]


@dataclass
class ProposalSchema:
    """Schema for candidate debt proposals generated by the residual compiler.
    
    All 8 fields are required for a valid proposal.
    """
    proposal_id: str
    title: str
    physics_domain: str
    physical_goal: str
    implementation_path: str
    machine_criteria: str
    source_node_id: str
    priority_score: float
    
    # Optional fields
    source_type: str = "limitation"  # "limitation" or "capability_gap"
    source_capability: Optional[str] = None
    evidence_grade: str = "WITHHELD"
    created_at: str = field(default_factory=lambda: datetime.utcnow().isoformat())
    dedup_matches: List[str] = field(default_factory=list)
    notes: Optional[str] = None
    
    def to_dict(self) -> dict:
        """Convert to dictionary."""
        return asdict(self)
    
    def validate(self) -> bool:
        """Validate that all required fields are present and non-empty."""
        for field_name in PROPOSAL_REQUIRED_FIELDS:
            value = getattr(self, field_name, None)
            if value is None or (isinstance(value, str) and not value.strip()):
                return False
        if not isinstance(self.priority_score, (int, float)):
            return False
        return True
    
    def to_json(self) -> str:
        """Convert to JSON string."""
        return json.dumps(self.to_dict(), ensure_ascii=False, indent=2)
    
    @classmethod
    def from_dict(cls, data: dict) -> "ProposalSchema":
        """Create from dictionary."""
        # Filter to only known fields
        known_fields = {f.name for f in cls.__dataclass_fields__.values()}
        filtered = {k: v for k, v in data.items() if k in known_fields}
        return cls(**filtered)
